graph = {1:[2,3], 2:[1,4,5], 3:[1,6], 4:[2], 5:[2], 6:[3]}

def bfs(graph, start):
    visited = []
    queue = deque([start])
    seen = {start}
    while queue:
        node = queue.popleft()
        visited.append(node)
        for nb in graph[node]:
            if nb not in seen:
                seen.add(nb)
                queue.append(nb)
    return visited

def dfs(graph, node, seen=None):
    if seen is None: seen = set()
    seen.add(node)
    result = [node]
    for nb in graph[node]:
        if nb not in seen:
            result += dfs(graph, nb, seen)
    return result

