def bfs_shortest_path(graph, start, end):
    queue = deque([(start, [start])])
    seen = {start}
    while queue:
        node, path = queue.popleft()
        if node == end:
            return path
        for nb in graph[node]:
            if nb not in seen:
                seen.add(nb)
                queue.append((nb, path + [nb]))
    return None

