class Stack:
    def __init__(self):
        self._data = []

    def push(self, item):
        self._data.append(item)

    def pop(self):
        return self._data.pop()

    def __str__(self):
        return f'Stack({self._data})'

    def __repr__(self):
        return f'Stack({self._data!r})'

    def __len__(self):
        return len(self._data)

    def __eq__(self, other):
        return isinstance(other, Stack) and self._data == other._data

