import heapq

def dijkstra(graph, start):
    # graph: {node: [(cost, neighbor), ...]}
    dist = {node: float('inf') for node in graph}
    dist[start] = 0
    heap = [(0, start)]  # (비용, 노드)
    while heap:
        cost, node = heapq.heappop(heap)
        if cost > dist[node]: continue  # 이미 처리된 경우 스킵
        for w, nb in graph[node]:
            new_cost = cost + w
            if new_cost < dist[nb]:
                dist[nb] = new_cost
                heapq.heappush(heap, (new_cost, nb))
    return dist

