class BIT:
    def __init__(self, n):
        self.n = n
        self.bit = [0] * (n + 1)

    def update(self, i, delta):  # 1-indexed
        while i <= self.n:
            self.bit[i] += delta
            i += i & (-i)  # 마지막 비트 추가

    def query(self, i):  # prefix sum [1..i]
        s = 0
        while i > 0:
            s += self.bit[i]
            i -= i & (-i)  # 마지막 비트 제거
        return s

    def range_query(self, l, r):
        return self.query(r) - self.query(l - 1)

