def bellman_ford(n, edges, src):
    INF = float('inf')
    dist = [INF] * n
    dist[src] = 0
    # V-1번 반복
    for _ in range(n-1):
        for u, v, w in edges:
            if dist[u] != INF and dist[u]+w < dist[v]:
                dist[v] = dist[u]+w
    # 음수 사이클 탐지
    for u, v, w in edges:
        if dist[u] != INF and dist[u]+w < dist[v]:
            return None  # 음수 사이클 존재
    return dist

