import numpy as np
def sieve_numpy(n):
    is_prime = np.ones(n+1, dtype=bool)
    is_prime[:2] = False
    for i in range(2, int(n**0.5)+1):
        if is_prime[i]:
            is_prime[i*i::i] = False
    return np.where(is_prime)[0].tolist()

